mapper.select:
select ba.id, ba.title, ba.summary, ba.cover_url, ba.article_type, ba.category_id, ba.author_id,
       ba.author_name, ba.is_top, ba.is_recommend, ba.status, ba.view_count,
       ba.like_count, ba.comment_count, ba.create_time, ba.update_time, ba.del_flag,
       bc.name as category_name
from blog_article ba
left join blog_category bc on ba.category_id = bc.id and bc.del_flag = 0

     and ba.title like concat('%', #{title}, '%')
     and ba.summary = #{summary}
     and ba.content = #{content}
     and ba.cover_url = #{coverUrl}
     and ba.article_type = #{articleType}
     and ba.category_id = #{categoryId}
     and ba.author_id = #{authorId}
     and ba.is_top = #{isTop}
     and ba.is_recommend = #{isRecommend}
     and ba.status = #{status}
     and ba.del_flag = #{delFlag}
     and ba.view_count = #{viewCount}
     and ba.like_count = #{likeCount}
     and ba.comment_count = #{commentCount}

order by ba.is_top desc, ba.create_time desc, ba.id desc

