mapper.insert:
insert into blog_article
(title, summary, content, content_md, format, article_type, seo_title, seo_keywords, seo_description, slug, cover_url, category_id, author_id, author_name, is_top, is_recommend, status, publish_time, view_count, like_count, comment_count, create_time, update_time, del_flag)
values
(#{title}, #{summary}, #{content}, #{contentMd}, #{format},

    #{articleType}
    'news'
, #{seoTitle}, #{seoKeywords}, #{seoDescription}, #{slug}, #{coverUrl}, #{categoryId}, #{authorId}, #{authorName}, #{isTop}, #{isRecommend}, #{status}, #{publishTime}, #{viewCount}, #{likeCount}, #{commentCount}, NOW(), NOW(),

    #{delFlag}
    0
)

mapper.update:
update blog_article
title = #{title}, summary = #{summary}, content = #{content}, content_md = #{contentMd}, format = #{format}, article_type = #{articleType}, seo_title = #{seoTitle}, seo_keywords = #{seoKeywords}, seo_description = #{seoDescription}, slug = #{slug}, cover_url = #{coverUrl}, category_id = #{categoryId}, author_id = #{authorId}, author_name = #{authorName}, is_top = #{isTop}, is_recommend = #{isRecommend}, status = #{status}, publish_time = #{publishTime}, view_count = #{viewCount}, like_count = #{likeCount}, comment_count = #{commentCount}, create_time = #{createTime}, update_time = #{updateTime}, del_flag = #{delFlag},
where id = #{id}

