select ba.id, ba.title, ba.summary, ba.cover_url, ba.category_id, ba.author_id, ba.author_name, ba.is_top, ba.is_recommend, ba.status, ba.view_count, ba.like_count, ba.comment_count, ba.create_time, ba.update_time, ba.del_flag, bc.name as category_name from blog_article ba left join blog_category bc on ba.category_id = bc.id and bc.del_flag = 0
ba.status = 1 and ba.del_flag = 0
and (ba.title like concat('%', #{keyword}, '%') or ba.content like concat('%', #{keyword}, '%'))
and ba.category_id = #{blogArticle.categoryId}
and ba.is_top = #{blogArticle.isTop}
and ba.is_recommend = #{blogArticle.isRecommend}
order by ba.create_time desc, ba.id desc

select ba.id, ba.title, ba.summary, ba.cover_url, ba.category_id, ba.author_id, ba.author_name, ba.is_top, ba.is_recommend, ba.status, ba.view_count, ba.like_count, ba.comment_count, ba.create_time, ba.update_time, ba.del_flag, bc.name as category_name, MATCH(ba.title, ba.content) AGAINST(#{keyword} IN NATURAL LANGUAGE MODE) as search_score from blog_article ba left join blog_category bc on ba.category_id = bc.id and bc.del_flag = 0
ba.status = 1 and ba.del_flag = 0
and MATCH(ba.title, ba.content) AGAINST(#{keyword} IN NATURAL LANGUAGE MODE)
and ba.category_id = #{blogArticle.categoryId}
and ba.is_top = #{blogArticle.isTop}
and ba.is_recommend = #{blogArticle.isRecommend}
order by search_score desc, ba.create_time desc, ba.id desc

select count(1) from blog_article
where del_flag = 0

    and status = #{status}

SELECT ba.id, ba.title, ba.summary, ba.cover_url, ba.category_id, ba.author_id, ba.author_name, ba.is_top, ba.is_recommend, ba.status, ba.view_count, ba.like_count, ba.comment_count, ba.create_time, ba.update_time, ba.del_flag, bc.name as category_name FROM blog_article ba LEFT JOIN blog_category bc ON ba.category_id = bc.id AND bc.del_flag = 0 WHERE ba.del_flag = 0
AND ba.status = #{status}
ORDER BY ba.view_count DESC, ba.create_time DESC, ba.id DESC

SELECT ba.id, ba.title, ba.summary, ba.content, ba.cover_url, ba.category_id, ba.author_id, ba.author_name, ba.is_top, ba.is_recommend, ba.status, ba.view_count, ba.like_count, ba.comment_count, ba.create_time, ba.update_time, ba.del_flag, bc.name as category_name FROM blog_article ba LEFT JOIN blog_category bc ON ba.category_id = bc.id AND bc.del_flag = 0 WHERE ba.del_flag = 0
AND ba.status = #{status}
AND DATE_FORMAT(ba.create_time, '%Y-%m') = #{archiveDate}
ORDER BY ba.create_time DESC, ba.id DESC

